import * as THREE from 'three/webgpu';
import { uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load ceramic-grain texture
  const textureUrl = config.assets?.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  const texture = ctx.textureLoader.load(textureUrl);

  // Atlas region dimensions (512×320 pixels)
  const regionWidth = 512;
  const regionHeight = 320;
  const aspectRatio = regionWidth / regionHeight;

  // Sprite dimensions in scene units
  const spriteWidth = 1.2;
  const spriteHeight = spriteWidth / aspectRatio;

  // Create background plane geometry
  const geometry = new THREE.PlaneGeometry(spriteWidth, spriteHeight);

  // Material with TSL texture node
  const textureNode = uniform(texture);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: textureNode,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text via fontAtlas (MSDF)
  if (ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createText({
      text: 'Pricing 2',
      fontSize: 0.2,
      color: new THREE.Color('#e8ecf2'),
      align: 'center',
      anchorX: 'center',
      anchorY: 'middle',
    });

    if (textMesh) {
      textMesh.position.z = 0.02;
      group.add(textMesh);
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  group.userData.handlers = {};

  return group;
}
